public class TotpProgressBar extends ProgressBar {
    private static final int PERIOD_DEFAULT = 30;

    /**
     * The progress bar is animated in steps of (at most) one second.
     */
    private static final long ANIM_STEP_MILLIS = 1000;

    private int _period = PERIOD_DEFAULT;
    private Handler _handler;
    private float _animDurationScale;

public void setPeriod(int period) {
    // don't allow a bogus period to be set, as that would break the
    // calculations in refresh() (and possibly cause a crash)
    if (!TotpInfo.isPeriodValid(period)) {
        period = PERIOD_DEFAULT;
    }

    _period = period;
}

