private void refresh() {
    // calculate the current progress the bar should start at
    int maxProgress = getMax();
    long periodMillis = (long) _period * 1000;
    long millisTillRotation = TotpInfo.getMillisTillNextRotation(_period);
    int currentProgress = (int) (maxProgress * ((double) millisTillRotation / periodMillis));

    // find out how much time is left until the next step of the animation, then
    // calculate the progress the bar should be at by that time
    // note: the progress bar may have a maximum that is lower than the number of
    // steps in this period, in which case multiple steps may result in the same progress
    long millisTillNextStep = millisTillRotation % ANIM_STEP_MILLIS;
    if (millisTillNextStep == 0) {
        millisTillNextStep = Math.min(ANIM_STEP_MILLIS, millisTillRotation);
    }
    long millisAtNextStep = millisTillRotation - millisTillNextStep;
    int animEnd = (int) (maxProgress * ((double) millisAtNextStep / periodMillis));

    if (_animDurationScale > 0) {
        // start progress animation, compensating for any changes to the animator duration scale settings
        long animDuration = (long) (millisTillNextStep / _animDurationScale);
        ObjectAnimator animation = ObjectAnimator.ofInt(this, "progress", currentProgress, animEnd);
        animation.setDuration(animDuration);
        animation.setInterpolator(new LinearInterpolator());
        animation.start();
    } else {
        // animations are disabled, so just update the progress directly
        setProgress(currentProgress);
    }

    // the animation only lasts for (at most) one second, so restart it after that
    _handler.postDelayed(this::refresh, millisTillNextStep);
}

